function scope(p,s){const ids=[p.id,...(aliases[p.id]||[])];if(p.id==='doctor-home'){if((s.tabs['doctor-profile']||0)===0)ids.push('doctor-visits');if(s.tabs['doctor-profile']===3)ids.push('doctor-account');}return rules.filter(r=>ids.includes(r.pageId));}
