const flag=(v,k,d=false)=>v[k]===undefined?d:[true,1,'1','true','yes'].includes(v[k]);
function mark(html,keys,c){const rs=scope(c.byId[c.current],c.state).filter(r=>(Array.isArray(keys)?keys:[keys]).some(k=>r.condition.includes(k)));if(!rs.length)return html;return `<div class="conditional-region" data-cids="${rs.map(r=>r.id).join(',')}" data-condition-label="后台/条件" title="${c.esc(rs.map(r=>r.condition).join('；'))}">${html}<button class="condition-pin" data-act="explain-condition" data-value="${rs.map(r=>r.id).join(',')}">条件</button></div>`;}
function inspector(p,c){const old=document.querySelector('#condition-panel');old?.remove();const list=scope(p,c.state);const section=document.createElement('section');section.id='condition-panel';section.innerHTML=`<h3>后台条件与页面状态 <span>${list.length}</span></h3><p class="condition-help">选择字段组合后查看真实组件差异。未选时沿用演示数据；多个组合冲突时以最后一次选择为准。</p>${list.length?list.map(r=>{const sel=c.state.variants?.[r.id]?.index??-1;return `<div class="condition-control"><label><span class="condition-origin">${({backend:"后台字段",role:"角色/权限",entry:"入口参数",local:"客户端状态/校验",derived:"派生条件"})[r.origin]||"条件"}</span>${c.esc(r.condition)}</label><select data-condition-select="${r.id}" aria-label="${c.esc(r.condition)}"><option value="-1">默认演示</option>${r.variants.map((v,i)=>`<option value="${i}" ${i===sel?'selected':''}>${c.esc(v.label)}</option>`).join('')}</select><small>${c.esc(sel>=0?r.variants[sel].effect:r.effect)}</small><a href="../${c.esc(r.source)}" target="_blank" rel="noopener">${c.esc(r.source.split('/').pop())}:${r.line}</a></div>`}).join(''):'<p class="condition-help">本页尚未完成条件穷举。没有列出条件，不表示代码不存在后台控制。</p>'}${c.act('clear-page-variants','清除本页状态组合','desktop-btn')}`;document.querySelector('#page-meta').after(section);const title=document.querySelector('#inspector-desc');if(title)title.textContent=(String(p.deviceReview||'').startsWith('已观察')?'已查看连接设备中的对应页面，并按当前可见结构校正；其余数据状态来自源码。':'按当前 iOS 源码继续校正；本页尚未逐页完成实机视觉核验。')+' 可在下方切换后台字段组合。'+(p.id==='workorder-create'?' '+p.note:'');}
function replaceRow(root,label,value,c,action=''){const rows=[...root.querySelectorAll('.row')];const r=rows.find(r=>r.querySelector('.label')?.textContent.trim()===label);if(!r)return;const val=r.querySelector('.value');if(val)val.innerHTML=value;if(action){r.dataset.go=action;r.removeAttribute('data-act');}}
