function validate(page,data,c){if(page!=='workorder-create')return true;const v=values(c.state,page);const config=Array.isArray(v.question_cfg)?v.question_cfg:[];for(let i=0;i<config.length;i++){const q=config[i],val=data['template_'+i];if(q.field_type==='sync')continue;if(!val||(Array.isArray(val)&&!val.length)){c.toast('请填写或选择'+q.key_name);return false;}if(q.field_type==='num'&&q.size_restrict&&(Number(val)<q.size_restrict.min||Number(val)>q.size_restrict.max)){c.toast(q.key_name+'超出示例模板范围');return false;}}return true;}
