function guard(from,to,c){const v=values(c.state,from);if(from==='doctor-info'&&to==='change-manager'&&v.transfer_cert_is_required===false){c.navigate('select-manager');return false}if(from==='doctor-info'&&to==='doctor-add'&&!(String(v.did??'100')==='0'&&(v.manager_id??'current')==='current')){c.toast('当前状态不显示编辑入口');return false}if(from==='order-detail'&&['order-address','order-invoice','order-refund'].includes(to)&&v.op_flag!==undefined&&!flag(v,'op_flag')){c.toast(v.op_msg||'暂不支持该操作！');return false}return true;}
